#pragma once
// Selects this build's MIDL display-class limits header (instruments#19).
//
// tools/midl_class.py (PlatformIO pre: script on every device env) maps the
// env's BOARD_ID_* / LCD_W x LCD_H to a class and defines YB_MIDL_CLASS_<ID>;
// the per-class headers under include/midl_gen/<class>/ are AUTO-GENERATED by
// tools/embed_manifest.py (`make embed-manifest`) and committed. A device
// (ESP_PLATFORM) build with no class selected is an error, never a silent
// square-480 fallback. Host builds (native tests, sims) default to square-480.
#if defined(YB_MIDL_CLASS_ROUND_360)
#include "midl_gen/round-360/limits.h"
#elif defined(YB_MIDL_CLASS_LANDSCAPE_800X480)
#include "midl_gen/landscape-800x480/limits.h"
#elif defined(YB_MIDL_CLASS_LANDSCAPE_1024X600)
#include "midl_gen/landscape-1024x600/limits.h"
#elif defined(YB_MIDL_CLASS_SQUARE_480) || !defined(ESP_PLATFORM)
#include "midl_gen/square-480/limits.h"
#else
#error "No MIDL display class for this env: add pre:tools/midl_class.py to its extra_scripts"
#endif
